//! CodeYourPCB Design Rule Check (DRC) Engine
//!
//! Validates PCB designs against manufacturer constraints before fabrication.
//! Uses the spatial index for efficient clearance checking with O(log n) queries.
//!
//! # Architecture
//!
//! DRC rules are implemented as structs that implement the [`DrcRule`] trait.
//! The engine runs all enabled rules against the board and collects violations.
//!
//! # Usage
//!
//! ```rust,ignore
//! use cypcb_drc::{run_drc, DesignRules, DrcResult, Preset};
//! use cypcb_world::BoardWorld;
//!
//! let world = BoardWorld::new();
//! // ... load board ...
//!
//! // Use a manufacturer preset
//! let rules = DesignRules::jlcpcb_2layer();
//! let result = run_drc(&world, &rules);
//!
//! // Or lookup by name (from DSL parsing)
//! let preset = Preset::from_name("pcbway").unwrap();
//! let rules = preset.rules();
//!
//! if result.passed() {
//!     println!("Board passes DRC!");
//! } else {
//!     println!("{} violations found", result.violation_count());
//!     for violation in &result.violations {
//!         println!("  {}: {}", violation.kind, violation.message);
//!     }
//! }
//! ```

pub mod presets;
pub mod rules;
pub mod violation;

pub use presets::{DesignRules, Preset};
pub use rules::DrcRule;
pub use violation::{DrcViolation, ViolationKind};

use cypcb_world::BoardWorld;

/// Result of running DRC on a board.
#[derive(Debug, Clone)]
pub struct DrcResult {
    /// List of violations found.
    pub violations: Vec<DrcViolation>,
    /// Time taken to run DRC in milliseconds (for performance tracking).
    pub duration_ms: u64,
}

impl DrcResult {
    /// Check if the board passed all checks.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DrcResult;
    ///
    /// let result = DrcResult { violations: vec![], duration_ms: 10 };
    /// assert!(result.passed());
    /// ```
    pub fn passed(&self) -> bool {
        self.violations.is_empty()
    }

    /// Number of violations found.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DrcResult;
    ///
    /// let result = DrcResult { violations: vec![], duration_ms: 10 };
    /// assert_eq!(result.violation_count(), 0);
    /// ```
    pub fn violation_count(&self) -> usize {
        self.violations.len()
    }
}

impl Default for DrcResult {
    fn default() -> Self {
        DrcResult {
            violations: Vec::new(),
            duration_ms: 0,
        }
    }
}

/// Run DRC on a board world.
///
/// Executes all enabled rules against the board and returns accumulated violations.
///
/// # Arguments
///
/// * `world` - The board world to check (mutable for ECS queries)
/// * `rules` - Design rules to check against
///
/// # Returns
///
/// DrcResult with all violations found.
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::{run_drc, DesignRules};
/// use cypcb_world::BoardWorld;
///
/// let mut world = BoardWorld::new();
/// let rules = DesignRules::default();
/// let result = run_drc(&mut world, &rules);
/// println!("DRC completed in {}ms", result.duration_ms);
/// ```
pub fn run_drc(world: &mut BoardWorld, rules: &DesignRules) -> DrcResult {
    // Timing - skip in WASM (Instant may not work reliably)
    #[cfg(not(target_arch = "wasm32"))]
    let start = std::time::Instant::now();

    let mut violations = Vec::new();

    // Create all rule checkers
    let checkers: Vec<Box<dyn DrcRule>> = vec![
        Box::new(rules::ClearanceRule),
        Box::new(rules::MinDrillSizeRule),
        Box::new(rules::MinTraceWidthRule),  // Placeholder - returns empty until traces exist
        Box::new(rules::UnconnectedPinRule),
        Box::new(rules::KeepoutRule),
    ];

    // Run each checker
    for checker in &checkers {
        violations.extend(checker.check(world, rules));
    }

    #[cfg(not(target_arch = "wasm32"))]
    let duration_ms = start.elapsed().as_millis() as u64;
    #[cfg(target_arch = "wasm32")]
    let duration_ms = 0; // Skip timing in WASM

    DrcResult {
        violations,
        duration_ms,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_drc_result_passed_empty() {
        let result = DrcResult::default();
        assert!(result.passed());
        assert_eq!(result.violation_count(), 0);
    }

    #[test]
    fn test_drc_result_with_violations() {
        use cypcb_core::Point;
        use bevy_ecs::entity::Entity;

        let result = DrcResult {
            violations: vec![
                DrcViolation::unconnected_pin(
                    Entity::from_raw(1),
                    "1",
                    "R1",
                    Point::ORIGIN,
                ),
            ],
            duration_ms: 5,
        };

        assert!(!result.passed());
        assert_eq!(result.violation_count(), 1);
    }

    #[test]
    fn test_run_drc_empty_world() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();
        let result = run_drc(&mut world, &rules);

        // Empty world should have no violations
        assert!(result.passed());
    }
}

//! Manufacturer preset design rules.
//!
//! This module provides pre-configured design rules for common PCB manufacturers.
//! Use the [`Preset`] enum for name-based lookup or call the constructor methods
//! directly on [`DesignRules`].
//!
//! # Supported Manufacturers
//!
//! - **JLCPCB**: Popular Chinese manufacturer with competitive pricing
//!   - 2-layer: Standard hobbyist option with 6mil minimum
//!   - 4-layer: Tighter tolerances available (4mil)
//!
//! - **PCBWay**: Alternative Chinese manufacturer with similar capabilities
//!
//! - **Prototype**: Relaxed rules for prototyping and hand assembly
//!
//! # Examples
//!
//! ```
//! use cypcb_drc::presets::{DesignRules, Preset};
//!
//! // Use preset enum for dynamic lookup
//! let preset = Preset::from_name("jlcpcb").unwrap();
//! let rules = preset.rules();
//!
//! // Or use constructor directly
//! let rules = DesignRules::jlcpcb_2layer();
//! ```

mod jlcpcb;
mod pcbway;

use cypcb_core::Nm;

/// Complete set of design rules for a board.
///
/// Contains minimum values for various design parameters that the DRC engine
/// validates against. Use the factory methods for manufacturer presets, or
/// create custom rules by constructing directly.
///
/// # Fields
///
/// - `min_clearance`: Minimum distance between copper features on the same layer
/// - `min_trace_width`: Minimum width of copper traces
/// - `min_drill_size`: Minimum mechanical drill hole diameter
/// - `min_via_drill`: Minimum via drill hole diameter
/// - `min_annular_ring`: Minimum width of copper ring around drill holes
/// - `min_silk_width`: Minimum silkscreen line width
/// - `min_edge_clearance`: Minimum distance from copper to board edge
///
/// # Examples
///
/// ```
/// use cypcb_drc::presets::DesignRules;
/// use cypcb_core::Nm;
///
/// // Use a manufacturer preset
/// let jlcpcb = DesignRules::jlcpcb_2layer();
/// assert_eq!(jlcpcb.min_clearance, Nm::from_mm(0.15));
///
/// // Or create custom rules
/// let custom = DesignRules {
///     min_clearance: Nm::from_mm(0.2),
///     min_trace_width: Nm::from_mm(0.25),
///     min_drill_size: Nm::from_mm(0.4),
///     min_via_drill: Nm::from_mm(0.3),
///     min_annular_ring: Nm::from_mm(0.2),
///     min_silk_width: Nm::from_mm(0.2),
///     min_edge_clearance: Nm::from_mm(0.5),
/// };
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DesignRules {
    /// Minimum clearance between copper features.
    pub min_clearance: Nm,
    /// Minimum trace width.
    pub min_trace_width: Nm,
    /// Minimum drill size (mechanical drilling).
    pub min_drill_size: Nm,
    /// Minimum via drill size.
    pub min_via_drill: Nm,
    /// Minimum annular ring width.
    pub min_annular_ring: Nm,
    /// Minimum silkscreen line width.
    pub min_silk_width: Nm,
    /// Minimum copper to board edge clearance.
    pub min_edge_clearance: Nm,
}

impl Default for DesignRules {
    /// Default rules use JLCPCB 2-layer values.
    ///
    /// JLCPCB is chosen as default because it's the most commonly used
    /// manufacturer for hobbyist PCB fabrication.
    fn default() -> Self {
        Self::jlcpcb_2layer()
    }
}

/// Manufacturer preset identifiers.
///
/// Use [`from_name`](Preset::from_name) for string-based lookup (useful for
/// DSL parsing) or match directly on the enum variants.
///
/// # Examples
///
/// ```
/// use cypcb_drc::presets::Preset;
///
/// // From string (e.g., parsed from DSL)
/// let preset = Preset::from_name("jlcpcb").unwrap();
/// assert_eq!(preset, Preset::Jlcpcb2Layer);
///
/// // Get rules from preset
/// let rules = preset.rules();
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Preset {
    /// JLCPCB standard 2-layer board.
    Jlcpcb2Layer,
    /// JLCPCB 4-layer board with tighter tolerances.
    Jlcpcb4Layer,
    /// PCBWay standard capabilities.
    PcbwayStandard,
    /// Relaxed rules for prototyping.
    Prototype,
}

impl Preset {
    /// Get the design rules for this preset.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    /// use cypcb_core::Nm;
    ///
    /// let rules = Preset::Jlcpcb2Layer.rules();
    /// assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
    /// ```
    pub fn rules(self) -> DesignRules {
        match self {
            Preset::Jlcpcb2Layer => DesignRules::jlcpcb_2layer(),
            Preset::Jlcpcb4Layer => DesignRules::jlcpcb_4layer(),
            Preset::PcbwayStandard => DesignRules::pcbway_standard(),
            Preset::Prototype => DesignRules::prototype(),
        }
    }

    /// Parse a preset from a string name.
    ///
    /// Accepts various aliases for convenience:
    /// - `"jlcpcb"` or `"jlcpcb_2layer"` -> [`Jlcpcb2Layer`](Preset::Jlcpcb2Layer)
    /// - `"jlcpcb_4layer"` -> [`Jlcpcb4Layer`](Preset::Jlcpcb4Layer)
    /// - `"pcbway"` or `"pcbway_standard"` -> [`PcbwayStandard`](Preset::PcbwayStandard)
    /// - `"prototype"` -> [`Prototype`](Preset::Prototype)
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    ///
    /// assert_eq!(Preset::from_name("jlcpcb"), Some(Preset::Jlcpcb2Layer));
    /// assert_eq!(Preset::from_name("jlcpcb_2layer"), Some(Preset::Jlcpcb2Layer));
    /// assert_eq!(Preset::from_name("pcbway"), Some(Preset::PcbwayStandard));
    /// assert_eq!(Preset::from_name("unknown"), None);
    /// ```
    pub fn from_name(name: &str) -> Option<Self> {
        match name {
            "jlcpcb" | "jlcpcb_2layer" => Some(Preset::Jlcpcb2Layer),
            "jlcpcb_4layer" => Some(Preset::Jlcpcb4Layer),
            "pcbway" | "pcbway_standard" => Some(Preset::PcbwayStandard),
            "prototype" => Some(Preset::Prototype),
            _ => None,
        }
    }

    /// Get the canonical name for this preset.
    ///
    /// Returns the primary string identifier used in DSL files.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    ///
    /// assert_eq!(Preset::Jlcpcb2Layer.name(), "jlcpcb_2layer");
    /// assert_eq!(Preset::PcbwayStandard.name(), "pcbway_standard");
    /// ```
    pub fn name(self) -> &'static str {
        match self {
            Preset::Jlcpcb2Layer => "jlcpcb_2layer",
            Preset::Jlcpcb4Layer => "jlcpcb_4layer",
            Preset::PcbwayStandard => "pcbway_standard",
            Preset::Prototype => "prototype",
        }
    }

    /// Get all available presets.
    ///
    /// Useful for generating documentation or CLI help text.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    ///
    /// let presets = Preset::all();
    /// assert_eq!(presets.len(), 4);
    /// ```
    pub fn all() -> &'static [Preset] {
        &[
            Preset::Jlcpcb2Layer,
            Preset::Jlcpcb4Layer,
            Preset::PcbwayStandard,
            Preset::Prototype,
        ]
    }
}

impl std::fmt::Display for Preset {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.name())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_jlcpcb_2layer_values() {
        let rules = DesignRules::jlcpcb_2layer();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
        assert_eq!(rules.min_trace_width, Nm::from_mm(0.15));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.3));
        assert_eq!(rules.min_via_drill, Nm::from_mm(0.2));
        assert_eq!(rules.min_annular_ring, Nm::from_mm(0.15));
        assert_eq!(rules.min_silk_width, Nm::from_mm(0.15));
        assert_eq!(rules.min_edge_clearance, Nm::from_mm(0.3));
    }

    #[test]
    fn test_jlcpcb_4layer_values() {
        let rules = DesignRules::jlcpcb_4layer();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.1));
        assert_eq!(rules.min_trace_width, Nm::from_mm(0.1));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.2));
        assert_eq!(rules.min_annular_ring, Nm::from_mm(0.125));
    }

    #[test]
    fn test_pcbway_standard_values() {
        let rules = DesignRules::pcbway_standard();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.2));
        assert_eq!(rules.min_silk_width, Nm::from_mm(0.22));
    }

    #[test]
    fn test_prototype_values() {
        let rules = DesignRules::prototype();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.2));
        assert_eq!(rules.min_trace_width, Nm::from_mm(0.25));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.4));
    }

    #[test]
    fn test_preset_from_name() {
        assert_eq!(Preset::from_name("jlcpcb"), Some(Preset::Jlcpcb2Layer));
        assert_eq!(Preset::from_name("jlcpcb_2layer"), Some(Preset::Jlcpcb2Layer));
        assert_eq!(Preset::from_name("jlcpcb_4layer"), Some(Preset::Jlcpcb4Layer));
        assert_eq!(Preset::from_name("pcbway"), Some(Preset::PcbwayStandard));
        assert_eq!(Preset::from_name("pcbway_standard"), Some(Preset::PcbwayStandard));
        assert_eq!(Preset::from_name("prototype"), Some(Preset::Prototype));
        assert_eq!(Preset::from_name("unknown"), None);
    }

    #[test]
    fn test_preset_rules_accessor() {
        let rules = Preset::Jlcpcb2Layer.rules();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.15));

        let rules = Preset::PcbwayStandard.rules();
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.2));
    }

    #[test]
    fn test_default_is_jlcpcb() {
        let default = DesignRules::default();
        let jlcpcb = DesignRules::jlcpcb_2layer();
        assert_eq!(default, jlcpcb);
    }

    #[test]
    fn test_prototype_has_larger_margins() {
        let proto = DesignRules::prototype();
        let jlcpcb = DesignRules::jlcpcb_2layer();
        assert!(proto.min_clearance > jlcpcb.min_clearance);
        assert!(proto.min_trace_width > jlcpcb.min_trace_width);
        assert!(proto.min_drill_size > jlcpcb.min_drill_size);
    }

    #[test]
    fn test_preset_name() {
        assert_eq!(Preset::Jlcpcb2Layer.name(), "jlcpcb_2layer");
        assert_eq!(Preset::Jlcpcb4Layer.name(), "jlcpcb_4layer");
        assert_eq!(Preset::PcbwayStandard.name(), "pcbway_standard");
        assert_eq!(Preset::Prototype.name(), "prototype");
    }

    #[test]
    fn test_preset_display() {
        assert_eq!(format!("{}", Preset::Jlcpcb2Layer), "jlcpcb_2layer");
        assert_eq!(format!("{}", Preset::PcbwayStandard), "pcbway_standard");
    }

    #[test]
    fn test_preset_all() {
        let all = Preset::all();
        assert_eq!(all.len(), 4);
        assert!(all.contains(&Preset::Jlcpcb2Layer));
        assert!(all.contains(&Preset::Jlcpcb4Layer));
        assert!(all.contains(&Preset::PcbwayStandard));
        assert!(all.contains(&Preset::Prototype));
    }

    #[test]
    fn test_preset_roundtrip() {
        // Verify name() -> from_name() roundtrips
        for preset in Preset::all() {
            let name = preset.name();
            let parsed = Preset::from_name(name).unwrap();
            assert_eq!(*preset, parsed);
        }
    }

    #[test]
    fn test_4layer_tighter_than_2layer() {
        let two = DesignRules::jlcpcb_2layer();
        let four = DesignRules::jlcpcb_4layer();
        assert!(four.min_clearance < two.min_clearance);
        assert!(four.min_trace_width < two.min_trace_width);
        assert!(four.min_drill_size < two.min_drill_size);
    }
}

//! DRC violation types.
//!
//! This module defines the types used to represent design rule violations.

use bevy_ecs::entity::Entity;
use cypcb_core::{Nm, Point};
use cypcb_parser::ast::Span;

/// A design rule violation.
///
/// Captures all information needed to display the violation to the user
/// and allow click-to-zoom functionality in the viewer.
#[derive(Debug, Clone)]
pub struct DrcViolation {
    /// Type of violation.
    pub kind: ViolationKind,
    /// Location on the board (for click-to-zoom).
    pub location: Point,
    /// Primary entity involved.
    pub entity: Entity,
    /// Secondary entity (for clearance violations).
    pub other_entity: Option<Entity>,
    /// Source span in the DSL file (if available).
    pub source_span: Option<Span>,
    /// Human-readable description.
    pub message: String,
}

/// Categories of design rule violations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ViolationKind {
    /// Clearance between two copper features is too small.
    Clearance,
    /// Trace width is below minimum (placeholder for future).
    TraceWidth,
    /// Drill hole size is below minimum.
    DrillSize,
    /// Pin has no net connection.
    UnconnectedPin,
    /// Via drill is below minimum (placeholder for future).
    ViaDrill,
    /// Annular ring is below minimum (placeholder for future).
    AnnularRing,
    /// Component placed in a keepout zone.
    KeepoutViolation,
}

impl std::fmt::Display for ViolationKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ViolationKind::Clearance => write!(f, "clearance"),
            ViolationKind::TraceWidth => write!(f, "trace-width"),
            ViolationKind::DrillSize => write!(f, "drill-size"),
            ViolationKind::UnconnectedPin => write!(f, "unconnected-pin"),
            ViolationKind::ViaDrill => write!(f, "via-drill"),
            ViolationKind::AnnularRing => write!(f, "annular-ring"),
            ViolationKind::KeepoutViolation => write!(f, "keepout-violation"),
        }
    }
}

impl DrcViolation {
    /// Create a clearance violation.
    ///
    /// # Arguments
    ///
    /// * `entity` - Primary entity involved
    /// * `other` - Secondary entity (the other item too close)
    /// * `actual` - Actual clearance distance
    /// * `required` - Required minimum clearance
    /// * `location` - Board location for click-to-zoom
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::entity::Entity;
    /// use cypcb_core::{Nm, Point};
    /// use cypcb_drc::DrcViolation;
    ///
    /// let violation = DrcViolation::clearance(
    ///     Entity::from_raw(1),
    ///     Entity::from_raw(2),
    ///     Nm::from_mm(0.1),
    ///     Nm::from_mm(0.15),
    ///     Point::from_mm(10.0, 20.0),
    /// );
    /// assert_eq!(violation.kind, cypcb_drc::ViolationKind::Clearance);
    /// ```
    pub fn clearance(
        entity: Entity,
        other: Entity,
        actual: Nm,
        required: Nm,
        location: Point,
    ) -> Self {
        DrcViolation {
            kind: ViolationKind::Clearance,
            location,
            entity,
            other_entity: Some(other),
            source_span: None,
            message: format!(
                "Clearance violation: {:.2}mm actual, {:.2}mm required",
                actual.to_mm(),
                required.to_mm(),
            ),
        }
    }

    /// Create a drill size violation.
    ///
    /// # Arguments
    ///
    /// * `entity` - Entity with the undersized drill
    /// * `actual` - Actual drill size
    /// * `required` - Required minimum drill size
    /// * `location` - Board location for click-to-zoom
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::entity::Entity;
    /// use cypcb_core::{Nm, Point};
    /// use cypcb_drc::DrcViolation;
    ///
    /// let violation = DrcViolation::drill_size(
    ///     Entity::from_raw(1),
    ///     Nm::from_mm(0.2),
    ///     Nm::from_mm(0.3),
    ///     Point::from_mm(10.0, 20.0),
    /// );
    /// assert_eq!(violation.kind, cypcb_drc::ViolationKind::DrillSize);
    /// ```
    pub fn drill_size(entity: Entity, actual: Nm, required: Nm, location: Point) -> Self {
        DrcViolation {
            kind: ViolationKind::DrillSize,
            location,
            entity,
            other_entity: None,
            source_span: None,
            message: format!(
                "Drill size violation: {:.2}mm actual, {:.2}mm minimum",
                actual.to_mm(),
                required.to_mm(),
            ),
        }
    }

    /// Create an unconnected pin violation.
    ///
    /// # Arguments
    ///
    /// * `entity` - Component entity with the unconnected pin
    /// * `pin` - Pin identifier (number or name)
    /// * `refdes` - Component reference designator
    /// * `location` - Board location for click-to-zoom
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::entity::Entity;
    /// use cypcb_core::Point;
    /// use cypcb_drc::DrcViolation;
    ///
    /// let violation = DrcViolation::unconnected_pin(
    ///     Entity::from_raw(1),
    ///     "1",
    ///     "R1",
    ///     Point::from_mm(10.0, 20.0),
    /// );
    /// assert_eq!(violation.kind, cypcb_drc::ViolationKind::UnconnectedPin);
    /// assert!(violation.message.contains("R1.1"));
    /// ```
    pub fn unconnected_pin(entity: Entity, pin: &str, refdes: &str, location: Point) -> Self {
        DrcViolation {
            kind: ViolationKind::UnconnectedPin,
            location,
            entity,
            other_entity: None,
            source_span: None,
            message: format!("Unconnected pin: {}.{}", refdes, pin),
        }
    }

    /// Create a keepout violation.
    ///
    /// # Arguments
    ///
    /// * `entity` - Component entity in the keepout zone
    /// * `zone_entity` - Zone entity being violated
    /// * `refdes` - Component reference designator
    /// * `zone_name` - Optional zone name (for error message)
    /// * `location` - Board location for click-to-zoom
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::entity::Entity;
    /// use cypcb_core::Point;
    /// use cypcb_drc::DrcViolation;
    ///
    /// let violation = DrcViolation::keepout(
    ///     Entity::from_raw(1),
    ///     Entity::from_raw(2),
    ///     "R1",
    ///     Some("antenna_clearance"),
    ///     Point::from_mm(15.0, 15.0),
    /// );
    /// assert_eq!(violation.kind, cypcb_drc::ViolationKind::KeepoutViolation);
    /// assert!(violation.message.contains("R1"));
    /// ```
    pub fn keepout(
        entity: Entity,
        zone_entity: Entity,
        refdes: &str,
        zone_name: Option<&str>,
        location: Point,
    ) -> Self {
        let zone_desc = zone_name
            .map(|n| format!("keepout zone '{}'", n))
            .unwrap_or_else(|| "keepout zone".to_string());
        DrcViolation {
            kind: ViolationKind::KeepoutViolation,
            location,
            entity,
            other_entity: Some(zone_entity),
            source_span: None,
            message: format!("Component {} placed in {}", refdes, zone_desc),
        }
    }

    /// Set the source span for this violation.
    ///
    /// This enables the DSL error display to show the exact source location.
    pub fn with_source_span(mut self, span: Span) -> Self {
        self.source_span = Some(span);
        self
    }

    /// Add pad information to a drill size violation message.
    ///
    /// Updates the message to include component refdes and pad number.
    pub fn with_pad_info(mut self, refdes: &str, pad_number: &str) -> Self {
        if self.kind == ViolationKind::DrillSize {
            // Parse existing message to get dimensions
            if let Some(rest) = self.message.strip_prefix("Drill size violation: ") {
                self.message = format!("Drill size violation at {}.{}: {}", refdes, pad_number, rest);
            }
        }
        self
    }
}

